																	"
																	class="inline-flex min-h-[44px] shrink-0 items-center gap-1.5 rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-sm font-medium text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50 disabled:cursor-not-allowed disabled:opacity-50 md:min-h-0"
																	@click="triggerPendukungCamera"
																>
																	<svg
																		xmlns="http://www.w3.org/2000/svg"
																		viewBox="0 0 24 24"
																		class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
																		fill="none"
																		stroke="currentColor"
																		stroke-width="2"
																		stroke-linecap="round"
																		stroke-linejoin="round"
																	>
																		<path
																			d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"
																		/>
																		<circle
																			cx="12"
																			cy="13"
																			r="3"
																		/>
																	</svg>
																	Foto
																</button>
																<span
																	class="min-w-0 flex-1 truncate text-xs text-ui-ink-gray-500"
																>
																	{{
																		pendukung.namaFile
																			? 'File langsung terupload saat dipilih'
																			: 'Pilih Nama File dulu'
																	}}
																</span>
															</div>
															<!-- Auto-upload saat file dipilih. -->
															<input
																ref="pendukungInput"
																type="file"
																accept=".jpg,.jpeg,.png,.pdf,image/jpeg,image/png,application/pdf"
																class="hidden"
																@change="onPendukungFileChange"
															/>
														</td>
													</tr>
												</tbody>
											</table>
										</div>
									</section>
								</template>
							</template>
						</div>
					</div>
				</div>
			</div>
		</div>

		<!-- ====== Bottom bar: Save (mode edit) atau Actions (mode baca) ====== -->
		<Transition
			enter-active-class="transition duration-200 ease-out"
			enter-from-class="translate-y-2 opacity-0"
			leave-active-class="transition duration-150 ease-in"
			leave-to-class="translate-y-2 opacity-0"
		>
			<div
				v-if="
					doc.data && (editMode || transitions.items.length || aksiPengajuanItems.length)
				"
				class="sticky bottom-0 z-20 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
			>
				<!-- Mode edit → tombol Save (full-width, biru) -->
				<button
					v-if="editMode"
					type="button"
					:disabled="saving || photoBusy"
					class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
					@click="saveDocument"
				>
					<svg
						v-if="saving"
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4 animate-spin"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M21 12a9 9 0 1 1-6.219-8.56" />
					</svg>
					{{ saving ? 'Menyimpan…' : 'Save' }}
				</button>
				<!-- Mode baca → Aksi Pengajuan (grup) + Actions (transisi workflow).
				     Tampil berdampingan bila keduanya tersedia; sendiri = full-width. -->
				<div v-else class="flex items-center gap-2">
					<!-- Aksi Pengajuan → grup Form Hasil / Surat Diskresi / Berkas Diserahkan.
					     Meniru grup tombol "Aksi Pengajuan" di desk (data_pengajuan.js). -->
					<button
						v-if="aksiPengajuanItems.length"
						type="button"
						class="flex flex-1 items-center justify-center gap-2 rounded-full border border-primary bg-ui-surface py-3 text-sm font-semibold text-primary shadow-sm transition hover:bg-primary/5 active:scale-[0.99]"
						@click="aksiPengajuanOpen = true"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M12 20h9" />
							<path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
						</svg>
						Aksi Pengajuan
					</button>
					<!-- Actions → transisi workflow (hanya bila ada aksi untuk user) -->
					<button
						v-if="transitions.items.length"
						type="button"
						class="flex flex-1 items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99]"
						@click="actionsOpen = true"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<circle cx="12" cy="12" r="1" />
							<circle cx="19" cy="12" r="1" />
							<circle cx="5" cy="12" r="1" />
						</svg>
						Actions
					</button>
				</div>
			</div>
		</Transition>

		<!-- ====== Bottom-sheet daftar Actions (animasi naik) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="actionsOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="actionsOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="actionsOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-4 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								Actions
							</h2>

							<p
								v-if="transitions.loading"
								class="py-3 text-center text-sm text-ui-ink-gray-400"
							>
								Memuat aksi…
							</p>
							<p
								v-else-if="!transitions.items.length"
								class="py-3 text-center text-sm text-ui-ink-gray-400"
							>
								Tidak ada aksi tersedia untuk Anda.
							</p>
							<div v-else class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="t in transitions.items"
									:key="t.action"
									type="button"
									:disabled="!!transitions.applying"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border border-ui-line-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5 disabled:opacity-50"
									@click="onActionClick(t.action)"
								>
									<span class="text-sm font-semibold text-ui-ink-gray-800">{{
										t.action
									}}</span>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
										>→ {{ t.next_state }}</span
									>
								</button>
							</div>
							<p
								v-if="transitions.applying"
								class="mt-3 text-center text-xs text-ui-ink-gray-400"
							>
								Menerapkan “{{ transitions.applying }}”…
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Bottom-sheet input aksi banding (alasan / PIC / keterangan) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="wfInput.open"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="wfInput.open = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="wfInput.open"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-1 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								{{ wfInput.title }}
							</h2>
							<p class="mb-4 text-center text-xs text-ui-ink-gray-400">
								Aksi: {{ wfInput.action }}
							</p>

							<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
								{{ wfInput.label }} <span class="text-ui-ink-red-500">*</span>
							</label>

							<!-- PIC Banding (Link User Juragan) -->
							<SelectMenu
								v-if="wfInput.kind === 'pic'"
								v-model="wfInput.pic"
								:options="wfInput.picOptions"
								:placeholder="wfInput.picLoading ? 'Memuat…' : 'Pilih pengguna…'"
								:btn-class="inputClass"
							/>
							<!-- Alasan / Keterangan (Small Text).
							     Bukan v-model: v-model menunda nilai selama keyboard Android
							     masih menyusun kata (composition), dan di WebView aplikasi native
							     nilai itu bisa belum masuk saat Simpan ditekan → dianggap kosong
							     ("Alasan banding wajib diisi"). @input mengisi tiap ketukan. -->
							<textarea
								v-else
								:value="wfInput.value"
								rows="8"
								@input="wfInput.value = $event.target.value"
								:class="[inputClass, 'min-h-[12rem] resize-y']"
								:placeholder="wfInput.label"
							/>

							<pre
								v-if="wfInput.error"
								class="mt-2 whitespace-pre-wrap text-xs text-ui-ink-red-600"
								>{{ wfInput.error }}</pre
							>

							<div class="mt-4 flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-full border border-ui-line-gray-300 bg-ui-surface py-3 text-sm font-semibold text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50"
									@click="wfInput.open = false"
								>
									Batal
								</button>
								<button
									type="button"
									:disabled="wfInput.submitting"
									class="flex-1 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary transition active:scale-[0.99] disabled:opacity-50"
									@click="submitWfInput"
								>
									{{ wfInput.submitting ? 'Menyimpan…' : 'Simpan & Lanjut' }}
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Bottom-sheet Aksi Pengajuan (grup aksi non-workflow) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="aksiPengajuanOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="aksiPengajuanOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="aksiPengajuanOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-4 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								Aksi Pengajuan
							</h2>
							<div class="space-y-2">
								<button
									v-for="item in aksiPengajuanItems"
									:key="item.key"
									type="button"
									class="flex w-full items-center justify-between gap-3 rounded-2xl border border-ui-line-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5"
									@click="runAksiPengajuan(item)"
								>
									<span class="flex min-w-0 items-center gap-3">
										<span
											class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"
										>
											<svg
												xmlns="http://www.w3.org/2000/svg"
												viewBox="0 0 24 24"
												class="h-4 w-4"
												fill="none"
												stroke="currentColor"
												stroke-width="2"
												stroke-linecap="round"
												stroke-linejoin="round"
												v-html="item.icon"
											/>
										</span>
										<span class="min-w-0">
											<span
												class="block truncate text-sm font-semibold text-ui-ink-gray-800"
												>{{ item.label }}</span
											>
											<span
												class="block truncate text-xs text-ui-ink-gray-400"
												>{{ item.hint }}</span
											>
										</span>
									</span>
									<svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
										fill="none"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path d="M9 18l6-6-6-6" />
									</svg>
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Bottom-sheet Form Hasil (pilih PDF Internal / Eksternal) ====== -->
		<Teleport to="body">
