// Textarea auto-tinggi: tumbuh mengikuti isi sampai batas (~300 karakter di font
// 12px), lebih dari itu → muncul scroll. min 44px (target sentuh). Dipakai via
// `v-autogrow` pada textarea field (alamat, analisa CMO, dll).
const AUTOGROW_MAX = 180
function fitTextarea(el) {
	if (!el) return
	el.style.height = 'auto'
	const h = Math.min(Math.max(el.scrollHeight, 44), AUTOGROW_MAX)
	el.style.height = `${h}px`
	el.style.overflowY = el.scrollHeight > AUTOGROW_MAX ? 'auto' : 'hidden'
}
const vAutogrow = {
	mounted(el) {
		el.addEventListener('input', () => fitTextarea(el))
		nextTick(() => fitTextarea(el))
	},
	updated(el) {
		nextTick(() => fitTextarea(el))
	},
}

const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'DataPengajuan' }, 'Data Pengajuan')
const name = computed(() => route.params.name)

// Judul di breadcrumb: pakai nama marketing; fallback ke ID dokumen kalau kosong.
const displayTitle = computed(() => doc.data?.marketing_full_name || name.value)

// Fetch satu dokumen. `auto: false` + refresh CSRF dulu (sama seperti list view).
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: 'Data Pengajuan', name: name.value }
	},
	auto: false,
})

// ---- Tab top-level (fungsi, ala CRM) --------------------------------------
const TABS = [
	{
		key: 'activity',
		label: 'Activity',
		icon: '<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',
	},
	{
		key: 'comments',
		label: 'Comments',
		icon: '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
	},
	{
		key: 'data',
		label: 'Data',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'attachments',
		label: 'Attachments',
		icon: '<path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/>',
	},
]
// Default ke "Data" — tab yang paling sering dibuka.
const activeTab = ref('data')

// Semua tab (Activity, Comments, Data, Attachments) SELALU bisa diakses,
// tak peduli status dokumen (termasuk Draft).
function tabEnabled() {
	return true
}

// ---- Mode baca/edit --------------------------------------------------------
// Detail bersifat READ-ONLY secara default (semua field terkunci). Boleh diedit
// mengikuti workflow "Flow Kredit" — PERSIS aturan desk (frappe.workflow.is_read_only):
// dokumen ber-workflow editable HANYA bila user punya salah satu role `allow_edit`
// pada state saat ini (mis. Draft→CMO, Proses CA→Credit Analyst, Proses Banding→
// Pembanding/CMO). Editabilitas per-field tetap disaring permlevel & read_only_depends_on.
const editMode = ref(false)

// Peta state → role allow_edit dari workflow (diambil server-side agar sinkron).
const wfStateField = ref(null)
const wfEditStates = ref({})
const wfLoaded = ref(false)
async function loadWorkflowEditMap() {
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_workflow_edit_map?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			wfStateField.value = msg.state_field || null
			wfEditStates.value = msg.states || {}
		}
	} catch (e) {
		/* fallback: tanpa data workflow → anggap tak boleh edit (aman) */
	} finally {
		wfLoaded.value = true
	}
}

// Boleh edit dokumen? Mirror PERSIS frappe.workflow.is_read_only (dibalik):
//  - belum tahu (map/role belum dimuat) → false (aman, kunci dulu)
//  - tak ada workflow (state_field null) → true
//  - status kosong → true
//  - selain itu → user punya salah satu role allow_edit pada status ini
// Tidak ada lagi pengecualian banding hardcode: editabilitas mengikuti allow_edit
// workflow apa adanya (mis. CA Rejected & Proses Banding = CMO; Banding Rejected =
// Administrator saja) supaya sama dengan desk.
const canEditDoc = computed(() => {
	if (!wfLoaded.value || !currentUser.rolesLoaded) return false
	if (!wfStateField.value) return true
	const status = doc.data?.status
	if (!status) return true
	const mine = currentUser.roles || []
	const allow = wfEditStates.value[status] || []
	return allow.some((r) => mine.includes(r))
})

function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
// Begitu dokumen jadi tak-boleh-edit (mis. pindah state) → kunci lagi & matikan editMode.
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})

// ---- Sub-tab tab "Data" = Tab Break, DI-RENDER DARI META DOCTYPE -----------
// Field, urutan (idx), tipe, & options diambil dari meta (getdoctype) supaya
// PERSIS mengikuti definisi Frappe — bukan hardcode yang bisa drift/acak.
const activeSubtab = ref('')
const metaFields = ref([])
// Batas lampiran dari DocType (max_attachments) — dipakai untuk cegatan di klien.
const maxAttachments = ref(0)
const metaError = ref('')
// Defined before dataTabs/watchers so initial rendering can safely read the flag.
const prosesPencairan = reactive({
	enabled: false,
	fotoEnabled: false,
	loaded: false,
	error: '',
	process: null,
	canSubmit: false,
})

// Nilai field yang bisa diedit (copy dari dokumen saat load).
const form = reactive({})

// ---- Status "dirty" untuk tombol Save -------------------------------------
// dirty = ada perubahan belum disimpan (edit field / upload / tambah-hapus file).
// applyingRemote = true saat kita mengisi form dari server (load/save/workflow) →
// supaya perubahan terprogram itu TIDAK ikut menandai dirty.
const dirty = ref(false)
const applyingRemote = ref(false)
const saving = ref(false)
const photoBusy = ref(false)

watch(
	form,
	() => {
		if (!applyingRemote.value) dirty.value = true
	},
	{ deep: true }
)

// Sinkronkan form dari dokumen server tanpa memicu dirty.
async function syncFormFromDoc() {
	applyingRemote.value = true
	try {
		Object.assign(form, doc.data || {})
		syncEndUserBbg()
		// Samakan tipe nilai Link → string (cocok dgn value <option> dropdown).
		for (const f of metaFields.value) {
			if (f.fieldtype === 'Link' && form[f.fieldname] != null && form[f.fieldname] !== '') {
				form[f.fieldname] = String(form[f.fieldname])
			}
		}
		await nextTick()
	} finally {
		applyingRemote.value = false
	}
	dirty.value = false
}

// Kelas input form editable (dipakai semua widget). Isi field = 12px (text-xs).
// Catatan: di bawah 16px, iOS akan zoom saat input difokus — diterima sesuai
// permintaan agar seluruh teks Data Pengajuan konsisten 12px.
const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Permlevel yang boleh DIBACA / DITULIS user (dari docperm × roles user). permlevel 0
// selalu boleh baca (user sudah bisa membuka dokumen ini). Meniru frappe.perm: field di
// permlevel tanpa hak baca → disembunyikan; punya baca tapi tanpa tulis → read-only.
// Permlevel yang boleh DIBACA / DITULIS user — SUMBER KEBENARAN = Frappe
// (Meta.get_permlevel_access via endpoint portal). JANGAN dihitung dari DocPerm
// mentah: akses Data Pengajuan untuk CMO datang lewat has_permission hook (bukan
// DocPerm), sehingga perhitungan manual keliru menyembunyikan field permlevel>0
// dan membuat tab pertama tampak kosong ("Memuat field…").
const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))

async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) return
		const json = await res.json()
		const msg = json.message || {}
		if (Array.isArray(msg.read)) readablePermlevels.value = new Set([0, ...msg.read])
		if (Array.isArray(msg.write)) writablePermlevels.value = new Set([0, ...msg.write])
	} catch (e) {
		/* fallback: hanya permlevel 0 */
	}
}
function canReadPermlevel(f) {
	return readablePermlevels.value.has(f.permlevel || 0)
}

// ---- Hasil Cek NIK & No KK (field HTML) -----------------------------------
// Gabungan cnkkp (Core via n8n) & cnkkpps. Desk memakai HTML tabel dari server;
// portal mengambil data terstruktur lalu menampilkannya sebagai kartu collapse.
// Riwayat pengajuan di dalamnya dibaca live, jadi dimuat ulang setiap dokumen
// berubah (mis. setelah aksi workflow).
const HASIL_CEK_NIK_FIELD = 'hasil_cek_nik_html'
const hasilCekNik = reactive({ data: null, docname: '' })

async function loadHasilCekNik() {
	const docname = name.value
	if (!docname) return
	if (hasilCekNik.docname !== docname) hasilCekNik.data = null
	try {
		const params = new URLSearchParams({ name: docname, output: 'data' })
		const res = await fetch(
			`/api/method/juragan.api.local.ceknik.get_hasil_cek_nik?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		if (name.value !== docname) return
		hasilCekNik.data = json.message?.data || null
		hasilCekNik.docname = docname
	} catch (e) {
		console.warn('Gagal memuat hasil cek NIK:', e)
	}
}

watch(
	() => [name.value, doc.data?.modified],
	([docname, modified]) => {
		if (docname && modified) loadHasilCekNik()
	}
)

// Field "Informasi Hasil" yang hanya relevan setelah ada hasil → sembunyikan
// selama nilainya kosong atau masih nilai default (mis. cnkkp = "Belum / Tidak
// ada data ditemukan"). Berlaku reaktif karena membaca `form`.
const HIDE_IF_EMPTY = new Set([
	'no_perjanjian',
	'tanggal_pencairan',
	'tanggal_hasil', // Tanggal Hasil CA
	'keputusan_credit_analyst',
	'cnkkp', // Hasil Cek NIK & No KK Internal
	'keterangan_cancel_approval',
])
function isEmptyOrDefault(f) {
	const v = form[f.fieldname]
	const empty = v == null || (typeof v === 'string' ? v.trim() === '' : v === '')
	if (empty) return true
	const def = f.default
	return def != null && def !== '' && String(v).trim() === String(def).trim()
}
// Nilai field kosong/null (0 & false TIDAK dianggap kosong).
function isFieldNull(f) {
	const v = form[f.fieldname]
	return v == null || (typeof v === 'string' ? v.trim() === '' : v === '')
}

// Susun tab → section → kolom → field dari meta (urut sesuai idx asli).
const dataTabs = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			if (
				(f.fieldname === 'proses_pencairan_tab' && !prosesPencairan.enabled) ||
				f.fieldname === 'foto_tab'
			) {
				curTab = null
				curSection = null
				curCol = null
				continue
			}
			curTab = { key: f.fieldname, label: f.label || f.fieldname, sections: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			continue
		}
		if (!curTab) continue
		if (ft === 'Section Break') {
			curCol = []
			curSection = {
				label: f.label || '',
				depends_on: f.depends_on,
				columns: [curCol],
			}
			curTab.sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				curTab.sections.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		// Lewati field non-input & yang disembunyikan.
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Table MultiSelect',
				'Attach',
				'Attach Image', // → dipindah ke tab Attachments
			].includes(ft) &&
			f.fieldname !== HASIL_CEK_NIK_FIELD
		)
			continue
		if (f.hidden) continue
		// permlevel tanpa hak baca → sembunyikan (persis form Frappe).
		if (!canReadPermlevel(f)) continue
		// Hasil Cek NIK → tampil hanya kalau server mengembalikan isi (cek sudah jalan).
		if (f.fieldname === HASIL_CEK_NIK_FIELD) {
			if (!hasilCekNik.data) continue
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				curTab.sections.push(curSection)
			}
			curCol.push(f)
			continue
		}
		// Field hasil tertentu → sembunyikan kalau nilainya kosong / masih default.
		if (HIDE_IF_EMPTY.has(f.fieldname) && isEmptyOrDefault(f)) continue
		// Field read-only yang KOSONG (null) → sembunyikan (perilaku Frappe: read-only
		// tanpa isi tidak ditampilkan). Termasuk read-only via read_only_depends_on
		// (mis. `kategori_enduser` yang terkunci selama status bukan "Proses CA") — jadi
		// tidak muncul sebagai "—" saat masih kosong. Begitu field jadi editable (status
		// Proses CA + role berhak), kondisi read-only bernilai false → tetap tampil.
		if (fieldLevelReadOnly(f) && isFieldNull(f)) continue
		// depends_on Frappe → sembunyikan kalau kondisinya tidak terpenuhi.
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			curTab.sections.push(curSection)
		}
		curCol.push(f)
	}
	// Buang kolom kosong (mis. Column Break tepat setelah Section Break bikin
	// kolom kosong di kiri), lalu buang section yang tak punya field sama sekali.
	for (const t of tabs) {
		t.sections = t.sections
			// Section Break depends_on → sembunyikan seluruh section by status.
			.filter((s) => evalCondition(s.depends_on))
			.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
			.filter((s) => s.columns.length)
	}
	return tabs
})

const SUBTABS = computed(() => dataTabs.value.map((t) => ({ key: t.key, label: t.label })))

// ---- Sub-tab "Proses Pencairan" (catatan kekurangan & catatan pencairan) ---
// Di desk keduanya field HTML yang digambar dari child table dokumen Proses
// Pencairan Pengajuan. dataTabs melewati fieldtype HTML karena bukan input,
// jadi sub-tab ini akan kosong kalau isinya tidak dirender sendiri.
const PROSES_PENCAIRAN_TAB = 'proses_pencairan_tab'
const isProsesPencairanSubtab = computed(
	() => prosesPencairan.enabled && activeSubtab.value === PROSES_PENCAIRAN_TAB
)

const catatanProses = reactive({
