// Timestamp relatif (tanpa library), gaya seperti gambar referensi.
function timeAgo(dateStr) {
	if (!dateStr) return ''
	const then = new Date(String(dateStr).replace(' ', 'T'))
	const sec = Math.floor((Date.now() - then.getTime()) / 1000)
	if (sec < 60) return 'just now'
	const min = Math.floor(sec / 60)
	if (min < 60) return `${min} minute${min > 1 ? 's' : ''} ago`
	const hr = Math.floor(min / 60)
	if (hr < 24) return `${hr} hour${hr > 1 ? 's' : ''} ago`
	const d = Math.floor(hr / 24)
	if (d === 1) return 'yesterday'
	if (d < 7) return `${d} days ago`
	const w = Math.floor(d / 7)
	if (w < 5) return `${w} week${w > 1 ? 's' : ''} ago`
	const mo = Math.floor(d / 30)
	if (mo < 12) return `${mo} month${mo > 1 ? 's' : ''} ago`
	const y = Math.floor(d / 365)
	return `${y} year${y > 1 ? 's' : ''} ago`
}

function escHtml(s) {
	return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}
function stripHtml(s) {
	return String(s)
		.replace(/<[^>]*>/g, '')
		.trim()
}
// Format nilai untuk timeline (meniru format_content_for_timeline Frappe):
// HTML → teks, dipotong 40 karakter, kosong/null → "".
function fmtTimelineVal(v) {
	let s = v == null ? '' : stripHtml(typeof v === 'object' ? JSON.stringify(v) : String(v))
	if (s.length > 40) s = s.slice(0, 40) + '...'
	if (s === '') return '&quot;&quot;'
	return escHtml(s)
}
function initials(nameStr) {
	return String(nameStr)
		.split(/\s+/)
		.filter(Boolean)
		.slice(0, 2)
		.map((w) => w[0]?.toUpperCase() || '')
		.join('')
}

// Susun timeline dari docinfo. Urut DESCENDING (terbaru di atas).
function buildTimeline(info) {
	const items = []
	const userName = (email) => info.user_info?.[email]?.fullname || email || 'Someone'

	// Entry "created" dari dokumen.
	if (doc.data) {
		items.push({
			key: 'created',
			type: 'created',
			user: userName(doc.data.owner),
			time: doc.data.creation,
			actionHtml: ' created this ',
		})
	}

	// Perubahan field dari Version (gabung jadi satu baris per versi).
	// Ikuti Frappe: pakai label meta, lewati field hidden, dan BATASI 3 perubahan.
	const dfByName = {}
	for (const f of metaFields.value) dfByName[f.fieldname] = f
	;(info.versions || []).forEach((v, vi) => {
		let data = {}
		try {
			data = JSON.parse(v.data || '{}')
		} catch (e) {
			data = {}
		}
		const changes = data.changed || []
		const parts = []
		for (const [field, oldVal, newVal] of changes) {
			if (field === 'docstatus') continue
			const df = dfByName[field]
			if (!df) continue // field tak ada di meta → lewati (spt Frappe)
			if (df.hidden && !df.show_on_timeline) continue // hidden → lewati
			const label = df.label || humanize(field)
			parts.push(
				`<b>${escHtml(label)}</b> from <b>${fmtTimelineVal(
					oldVal
				)}</b> to <b>${fmtTimelineVal(newVal)}</b>`
			)
			if (parts.length >= 3) break // Frappe membatasi 3 perubahan per versi
		}
		if (parts.length) {
			items.push({
				key: `v-${vi}`,
				type: 'change',
				user: userName(v.owner),
				time: v.creation,
				actionHtml: ` changed the value of ${parts.join(', ')} `,
			})
		} else if (!changes.length) {
			items.push({
				key: `v-${vi}`,
				type: 'change',
				user: userName(v.owner),
				time: v.creation,
				actionHtml: ' updated this ',
			})
		}
	})

	// Perubahan workflow/status (ikon git-branch). content = nama state.
	;(info.workflow_logs || []).forEach((c, ci) => {
		items.push({
			key: `w-${ci}`,
			type: 'workflow',
			user: userName(c.owner),
			time: c.creation,
			actionHtml: ` <b>${escHtml(stripHtml(c.content || ''))}</b> `,
		})
	})

	// Lampiran: "Attachment" (paperclip) & "Attachment Removed" (tong sampah).
	;(info.attachment_logs || []).forEach((c, ci) => {
		const removed = c.comment_type === 'Attachment Removed'
		const fileName = escHtml(stripHtml(c.content || ''))
		items.push({
			key: `a-${ci}`,
			type: removed ? 'attachment_removed' : 'attachment',
			user: userName(c.owner),
			time: c.creation,
			actionHtml: removed
				? ` removed attachment <b>${fileName}</b> `
				: ` attached <b>${fileName}</b> `,
		})
	})

	// Assignment (di-assign / selesai assign) — ikon user.
	;(info.assignment_logs || []).forEach((c, ci) => {
		items.push({
			key: `as-${ci}`,
			type: 'assignment',
			user: userName(c.owner),
			time: c.creation,
			actionHtml: ` ${c.content || ''} `,
		})
	})

	// Info / Edit / Label (mis. "marked as ...") — ikon info.
	;(info.info_logs || []).forEach((c, ci) => {
		items.push({
			key: `i-${ci}`,
			type: 'info',
			user: userName(c.owner),
			time: c.creation,
			actionHtml: ` ${c.content || ''} `,
		})
	})

	// Komentar (kartu). content sudah HTML dari backend.
	;(info.comments || []).forEach((c, ci) => {
		items.push({
			key: `c-${ci}`,
			type: 'comment',
			user: userName(c.owner),
			time: c.creation,
			content: c.content,
		})
	})

	// Urut terbaru di atas.
	items.sort(
		(a, b) =>
			new Date(String(b.time).replace(' ', 'T')) - new Date(String(a.time).replace(' ', 'T'))
	)
	return items
}

