// Helper umum: upload satu file → kembalikan { file_url, file_name }.
// Endpoint khusus portal, BUKAN /api/method/upload_file bawaan Frappe: file
// sengaja belum ditempelkan ke dokumen supaya tidak memakan kuota lampiran
// selama user belum menekan Save. Penempelannya diurus server saat dokumen
// disimpan (lihat data_pengajuan/attachments.py).
async function uploadRawFile(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('docname', name.value)
	const res = await fetch('/api/method/juragan.api.portal.data_pengajuan.upload_lampiran', {
		method: 'POST',
		credentials: 'include',
		// JANGAN set Content-Type → biar browser pasang boundary multipart.
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}

// Simpan dokumen via frappe.client.save (POST → butuh CSRF).
