	return json.message
}

// Batas & validasi file (ekstensi + ukuran). `exts` = daftar ekstensi yang boleh.
const MAX_FILE_MB = 3
function validateFile(file, exts) {
	const ext = (file.name.split('.').pop() || '').toLowerCase()
	if (!exts.includes(ext)) {
		return `Format file harus ${exts.map((e) => e.toUpperCase()).join(', ')}.`
	}
	if (file.size > MAX_FILE_MB * 1024 * 1024) {
		return `Ukuran file maksimal ${MAX_FILE_MB} MB.`
	}
	return ''
}

// --- File Kredit (field Attach: ktp / ktp_2 / ktp_3) — hanya PDF ---
const kreditInput = ref(null)
const pendingKreditField = ref(null)
const kreditUploading = ref('')
const kreditDeleting = ref('')
const kreditError = ref('')

// Hapus File Kredit → kosongkan nilai field (staged; benar-benar tersimpan saat Save).
function deleteKreditFile(f) {
	if (isAttachReadOnly(f)) return
	askConfirm(`Hapus file pada "${f.label}"?`, () => {
		kreditError.value = ''
		form[f.fieldname] = '' // tandai dirty → tombol Save muncul
	})
}

// Terkunci bila field read-only (read_only statis / read_only_depends_on ikut status).
function isAttachReadOnly(f) {
	return isFieldReadOnly(f)
}

function triggerKreditPick(f) {
	if (isAttachReadOnly(f)) return
	pendingKreditField.value = f
	kreditError.value = ''
	if (kreditInput.value) {
		kreditInput.value.value = '' // reset → file yang sama bisa dipilih ulang
		kreditInput.value.click()
	}
}

async function onKreditFileChange(e) {
	const file = e.target.files && e.target.files[0]
	const f = pendingKreditField.value
	if (!file || !f) return
	// Hanya PDF, maks 3 MB.
	const verr = validateFile(file, ['pdf'])
	if (verr) {
		kreditError.value = `${f.label}: ${verr}`
		pendingKreditField.value = null
		return
	}
	const qerr = attachmentQuotaError(Boolean(form[f.fieldname]))
	if (qerr) {
		kreditError.value = qerr
		pendingKreditField.value = null
		return
	}
	kreditUploading.value = f.fieldname
	kreditError.value = ''
	try {
		// Upload fisik file saja (tanpa fieldname → tidak langsung di-set ke dokumen).
		// Nilai field di-stage ke form → tersimpan saat user menekan Save.
		const fileDoc = await uploadRawFile(file)
		form[f.fieldname] = fileDoc.file_url // tandai dirty
	} catch (err) {
		kreditError.value = err.message || String(err)
		notifyError(err, 'Gagal mengunggah file')
	} finally {
		kreditUploading.value = ''
		pendingKreditField.value = null
	}
}

