// Tombol Form Hasil HANYA muncul pada status: CA Approved, CA Rejected,
// Banding Approved, Banding Rejected.
const FORM_HASIL_STATUSES = new Set([
	'CA Approved',
	'CA Rejected',
	'Banding Approved',
	'Banding Rejected',
])
const showFormHasil = computed(() => FORM_HASIL_STATUSES.has((doc.data?.status || '').trim()))

// Print format "Internal" mengikuti logika desk: CA → "Form Hasil CA",
// Banding → "Form Hasil Banding". Untuk "Sudah Pencairan" ikut keputusan
// (CA Approve → Form Hasil CA; CA Reject + Banding Approve → Form Hasil Banding).
// Fallback → "Form Hasil CA". Eksternal selalu "Surat Persetujuan Pembiayaan".
const internalPrintFormat = computed(() => {
	const status = (doc.data?.status || '').trim()
	const MAP = {
		'CA Approved': 'Form Hasil CA',
		'CA Rejected': 'Form Hasil CA',
		'Banding Approved': 'Form Hasil Banding',
		'Banding Rejected': 'Form Hasil Banding',
	}
	let fmt = MAP[status]
	if (status === 'Sudah Pencairan') {
		const ca = doc.data?.keputusan_credit_analyst
		const banding = doc.data?.keputusan_banding
		if (ca === 'Approve') fmt = 'Form Hasil CA'
		else if (ca === 'Reject' && banding === 'Approve') fmt = 'Form Hasil Banding'
	}
	return fmt || 'Form Hasil CA'
})

