// Print format Surat Diskresi per tipe (samakan dengan print_format_rules di
// Document Signing Config). Sebelumnya di sini dipakai nama "Form Surat Diskresi"
// yang TIDAK ADA — Frappe tidak error untuk format tak dikenal, ia diam-diam
// jatuh ke print format "Standard", jadi yang keluar PDF generik (±20 KB)
// alih-alih form asli (±66 KB).
const DISKRESI_PRINT_FORMATS = {
	'Kelengkapan Berkas': 'Surat Diskresi Kelengkapan Berkas QR',
	'Pengurangan Angsuran': 'Surat Diskresi Pengurangan Angsuran QR',
}

// Buka PDF Surat Diskresi di viewer in-app. Mengikuti surat_diskresi.js desk:
// utamakan PDF bertanda tangan dari Document Signing Log; kalau dokumennya
// disetujui sebelum signing config ada, fallback render print format sesuai tipe.
async function downloadDiskresiPdf(diskresi) {
	const row = typeof diskresi === 'string' ? { name: diskresi } : diskresi || {}
	let fileUrl = ''
	try {
		const params = new URLSearchParams({
			reference_doctype: 'Surat Diskresi',
			reference_name: row.name,
		})
		const res = await fetch(
			`/api/method/juragan.juragan.doctype.document_signing_log.document_signing_log.get_latest_signed_pdf?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) fileUrl = (await res.json().catch(() => ({})))?.message || ''
	} catch (e) {
		// Signed PDF tak terjangkau → lanjut render live di bawah.
	}
	if (!fileUrl) {
		const fmt =
			DISKRESI_PRINT_FORMATS[row.tipe_diskresi] ||
			DISKRESI_PRINT_FORMATS['Kelengkapan Berkas']
		fileUrl =
			`/api/method/frappe.utils.print_format.download_pdf` +
			`?doctype=${encodeURIComponent('Surat Diskresi')}` +
			`&name=${encodeURIComponent(row.name)}` +
			`&format=${encodeURIComponent(fmt)}` +
			`&no_letterhead=0`
	}
	openPdf(fileUrl, row.name)
}

