// Buat Surat Diskresi via whitelist create_from_pengajuan (validasi meniru desk).
async function submitDiskresi() {
	diskresiCreate.error = ''
	const tipe = (diskresiCreate.tipe || '').trim()
	if (!tipe) {
		diskresiCreate.error = 'Tipe Diskresi wajib diisi.'
		return
	}
	if (!diskresiCreate.alasan.trim()) {
		diskresiCreate.error = 'Keterangan wajib diisi.'
		return
	}
	if (isDiskresiPengurangan.value) {
		const angsuran = Number(doc.data?.angsuran || 0)
		const nominal = Number(diskresiCreate.nominal || 0)
		if (nominal <= 0) {
			diskresiCreate.error =
				'Nominal Pengurangan wajib diisi untuk tipe Pengurangan Angsuran.'
			return
		}
		if (angsuran - nominal <= 0) {
			diskresiCreate.error = `Angsuran Baru harus lebih dari 0. Pastikan Nominal Pengurangan tidak lebih dari atau sama dengan Angsuran (${currencyDisplay(
				angsuran
			)}).`
			return
		}
	}
	diskresiCreate.submitting = true
	try {
		const res = await fetch(
			'/api/method/juragan.juragan.doctype.surat_diskresi.surat_diskresi.create_from_pengajuan',
			{
				method: 'POST',
				credentials: 'include',
				headers: {
					'Content-Type': 'application/json',
					Accept: 'application/json',
					'X-Frappe-CSRF-Token': window.csrf_token || '',
				},
				body: JSON.stringify({
					data_pengajuan: name.value,
					tipe_diskresi: tipe,
					alasan_diskresi: diskresiCreate.alasan,
					nominal_pengurangan: isDiskresiPengurangan.value
						? Number(diskresiCreate.nominal || 0)
						: 0,
					file_pendukung: diskresiCreate.filePendukung || null,
				}),
			}
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		diskresiCreate.open = false
		await loadDiskresiList()
		loadActivity()
		notifySuccess('Surat Diskresi berhasil dibuat.')
	} catch (e) {
		diskresiCreate.error = e.message || String(e)
		notifyError(e, 'Gagal membuat Surat Diskresi')
	} finally {
		diskresiCreate.submitting = false
	}
}

// ---- Berkas Sudah Diserahkan / Buka Proses Pencairan ----------------------
// Paritas dgn setup_proses_pencairan_button() di desk (data_pengajuan.js). Desk
// membaca feature flag dari frappe.boot & mengecek peran di klien; portal tidak
// punya boot, jadi flag + aturan peran dihitung server lewat endpoint portal dan
// hanya boolean-nya yang dikirim (site_config tetap privat).

async function loadProsesPencairanAction() {
	if (!name.value) return
	prosesPencairan.loaded = false
	prosesPencairan.error = ''
	try {
		const params = new URLSearchParams({ data_pengajuan: name.value })
		const res = await fetch(
			`/api/method/juragan.api.portal.data_pengajuan.get_proses_pencairan_action?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok || json.exc || json.exception) throw new Error(`HTTP ${res.status}`)
		const state = json.message || {}
		if (typeof state.enabled !== 'boolean' || typeof state.foto_enabled !== 'boolean') {
			throw new Error('Feature flag tidak tersedia pada respons server.')
		}
		prosesPencairan.enabled = !!state.enabled
		prosesPencairan.fotoEnabled = !!state.foto_enabled
		prosesPencairan.process = state.process || null
		prosesPencairan.canSubmit = !!state.can_submit
	} catch (e) {
		// Gagal cek → sembunyikan aksi (jangan tampilkan tombol yang pasti ditolak server).
		prosesPencairan.enabled = false
		prosesPencairan.fotoEnabled = false
		prosesPencairan.process = null
		prosesPencairan.canSubmit = false
		prosesPencairan.error = `Pengaturan lampiran tidak dapat dimuat: ${e.message || e}`
	} finally {
		prosesPencairan.loaded = true
	}
}

