	} else if (prosesPencairan.enabled && prosesPencairan.canSubmit) {
		items.push({
			key: 'serah-berkas',
			label: 'Berkas Sudah Diserahkan',
			hint: 'Buat proses pencairan ke Backoffice',
			icon: ICON_BERKAS,
			run: openBerkasSerah,
		})
	}
	return items
})

function runAksiPengajuan(item) {
	aksiPengajuanOpen.value = false
	item.run()
}

// ---- Workflow Flow Kredit (transisi state per role) ------------------------
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '' })

// Pesan error Frappe yang manusiawi dari response.
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return htmlToText(
				arr
					.map((m) => {
						try {
							return JSON.parse(m).message
						} catch (e) {
							return m
						}
					})
					.join('\n')
			)
		}
	} catch (e) {
		/* ignore */
	}
	return htmlToText((json && (json.exception || json.message)) || '')
}

// Daftar transisi valid dari state sekarang sesuai role user (endpoint Frappe).
async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		transitions.items = json.message || []
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}

// Terapkan aksi workflow → server pindah state, lalu refresh dok/timeline/transisi.
async function applyAction(action) {
	transitions.applying = action
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		await syncFormFromDoc()
		loadActivity()
		loadTransitions()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

// ---- Input tambahan sebelum aksi workflow (meniru desk before_workflow_action) --
// Sebagian aksi butuh input dulu lewat modal, baru aksinya dijalankan:
//   - APPEAL (Ajukan Banding / Rekom Banding / Tidak Rekom Banding) → alasan_banding
//   - REJECT (Reject)                                               → banding_ke (PIC)
//   - CANCEL (Cancel Approval)                                      → keterangan_cancel_approval
// Pencocokan EXACT (lowercase) — persis logika desk (data_pengajuan.js).
const REJECT_KEYS = ['reject', 'tolak']
const APPEAL_KEYS = ['ajukan banding', 'rekom banding', 'tidak rekom banding']
const CANCEL_KEYS = ['cancel approval']

const wfInput = reactive({
	open: false,
	action: '',
	kind: '', // 'alasan' | 'pic' | 'cancel'
	title: '',
	label: '',
	value: '', // untuk alasan / keterangan (textarea)
	pic: '', // untuk banding_ke (Link)
	picOptions: [],
	picLoading: false,
	error: '',
	submitting: false,
})

// Gerbang klik tombol aksi: buka modal input dulu bila perlu, kalau tidak langsung apply.
function onActionClick(action) {
	const act = String(action).trim().toLowerCase()
	if (APPEAL_KEYS.includes(act)) openWfInput(action, 'alasan')
	else if (REJECT_KEYS.includes(act)) openWfInput(action, 'pic')
	else if (CANCEL_KEYS.includes(act)) openWfInput(action, 'cancel')
	else applyAction(action)
}

function openWfInput(action, kind) {
	wfInput.action = action
	wfInput.kind = kind
	wfInput.value = ''
	wfInput.pic = ''
	wfInput.error = ''
	if (kind === 'alasan') {
		wfInput.title = 'Alasan Banding'
		wfInput.label = 'Alasan Banding'
		wfInput.value = doc.data?.alasan_banding || ''
	} else if (kind === 'cancel') {
		wfInput.title = 'Keterangan Cancel Approval'
		wfInput.label = 'Alasan Pembatalan'
		wfInput.value = doc.data?.keterangan_cancel_approval || ''
	} else if (kind === 'pic') {
		wfInput.title = 'Pilih Tujuan Banding'
		wfInput.label = 'Banding Ke'
		wfInput.pic = doc.data?.banding_ke || ''
		loadPicBandingOptions()
	}
	actionsOpen.value = false
	wfInput.open = true
}

// Opsi PIC Banding = User Juragan dengan profile_completed & pic_banding (sama filter desk).
async function loadPicBandingOptions() {
	wfInput.picLoading = true
	wfInput.picOptions = []
	try {
		const params = new URLSearchParams({
			doctype: 'User Juragan',
			// value = name (user_id/email, disimpan ke banding_ke) tapi label = nama_lengkap
			// (title_field User Juragan) supaya tampil nama, bukan email.
			fields: JSON.stringify(['name', 'nama_lengkap']),
			filters: JSON.stringify([
				['profile_completed', '=', 1],
				['pic_banding', '=', 1],
			]),
			limit_page_length: '0',
			order_by: 'nama_lengkap asc',
		})
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		wfInput.picOptions = (json.message || []).map((r) => ({
			value: String(r.name),
			label: String(r.nama_lengkap || r.name),
		}))
	} catch (e) {
		wfInput.picOptions = []
	} finally {
		wfInput.picLoading = false
	}
}

// Simpan satu field ke dokumen di server (frappe.client.set_value, POST → butuh CSRF).
async function setDocField(fieldname, value) {
	const res = await fetch('/api/method/frappe.client.set_value', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doctype: 'Data Pengajuan', name: name.value, fieldname, value }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}

// Validasi → SIMPAN nilai ke dokumen dulu → jalankan aksi. Sama dengan desk
// (frm.set_value + frm.save sebelum aksi): apply_workflow di server memanggil
// doc.load_from_db(), jadi nilai yang hanya dititipkan di doc.data ikut terbuang
// (alasan_banding kosong, dan syarat transisi yang membaca banding_ke salah).
async function submitWfInput() {
	if (wfInput.submitting) return
	if (wfInput.kind === 'pic') {
		if (!wfInput.pic) {
			wfInput.error = 'Silakan pilih pengguna.'
			return
		}
	} else if (!wfInput.value.trim()) {
		wfInput.error =
			wfInput.kind === 'alasan'
				? 'Alasan banding wajib diisi.'
				: 'Keterangan pembatalan wajib diisi.'
		return
	}
	wfInput.submitting = true
	wfInput.error = ''
	try {
		const fieldname = {
			alasan: 'alasan_banding',
			cancel: 'keterangan_cancel_approval',
			pic: 'banding_ke',
		}[wfInput.kind]
		const value = wfInput.kind === 'pic' ? wfInput.pic : wfInput.value.trim()
		if ((doc.data?.[fieldname] ?? '') !== value) {
			try {
				await setDocField(fieldname, value)
			} catch (e) {
				wfInput.error = e.message || 'Gagal menyimpan isian.'
				return
			}
		}
		doc.data[fieldname] = value
		const action = wfInput.action
		wfInput.open = false
		await applyAction(action)
	} finally {
		wfInput.submitting = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	// Begitu dokumen selesai di-fetch, langsung ambil transisi workflow (paralel
	// dengan meta/permlevel yang biasanya lebih lambat) → tombol Actions bawah
	// tidak muncul terlambat.
	await Promise.all([
		loadMeta(),
		doc.fetch().then(() => loadTransitions()),
		loadPermlevelAccess(),
		loadWorkflowEditMap(),
	])
	// Isi nilai field editable dari dokumen (sekaligus reset dirty).
	await syncFormFromDoc()
	// Unit internal (MOKAS): hitung ulang flag dealer untuk visibilitas motor_tarikan
	// (tanpa mengosongkan unit tersimpan), lalu aktifkan watcher dealer.
	await loadDealerMokasList()
	await syncDealerMokasFlag({ clearUnit: false })
	dealerReady.value = true
	// Semua sumber penentu visibilitas field (meta + permlevel + form) sudah siap →
	// baru tetapkan sub-tab default ("Data Nasabah").
	coreLoaded.value = true
	await nextTick()
	initActiveSubtab()
	// Elemen header & tab strip sudah ter-render → ukur tinggi untuk offset sticky.
	measureSticky()
	setupStickyObservers()
	resolveAllLinks()
	loadActivity()
	loadComments()
	loadPendukungOptions()
})
</script>
